fts5.h1_f:
CREATE VIRTUAL TABLE mensagens_fts USING fts5(
  conteúdo, -- coluna tokenizada
  ID_quarto UNINDEXED,
  tokenize = 'unicode61 remove_diacritics 2'
);
consulta: SELECT rowid FROM mensagens_fts WHERE conteúdo MATCH 'foo'

